static boolean connectAndPing(String dbName) {
  try (Connection c = DriverManager.getConnection("jdbc:h2:mem:" + dbName + ";DB_CLOSE_DELAY=-1")) {
    c.createStatement().executeQuery("SELECT 1");
    return true;
  } catch (SQLException e) { return false; }
}

