static void printTable(Connection conn, String tableName) throws SQLException {
  System.out.println(conn.getMetaData().getURL());
  try (ResultSet rs = conn.createStatement().executeQuery("SELECT * FROM " + tableName)) {
    while (rs.next()) System.out.println(rs.getObject(1) + " | " + rs.getObject(2));
  }
}

