static void executeDdl(Connection c, String sql) throws SQLException { c.createStatement().execute(sql); }
static int insertRow(Connection c, String sql) throws SQLException { return c.createStatement().executeUpdate(sql); }
static List<String> queryAll(Connection c, String sql) throws SQLException {
  List<String> out = new ArrayList<>();
  try (ResultSet rs = c.createStatement().executeQuery(sql)) { while (rs.next()) out.add(rs.getObject(1) + ""); }
  return out;
}

