class SimpleRepository {
  private final Connection conn;
  SimpleRepository(Connection conn) { this.conn = conn; }
  void create() throws SQLException { conn.createStatement().execute("CREATE TABLE notes (id IDENTITY PRIMARY KEY, content VARCHAR(200))"); }
  void insertOne(String content) throws SQLException { conn.createStatement().executeUpdate("INSERT INTO notes (content) VALUES ('" + content + "')"); }
  List<String> findAll() throws SQLException {
    List<String> out = new ArrayList<>();
    try (ResultSet rs = conn.createStatement().executeQuery("SELECT content FROM notes")) { while (rs.next()) out.add(rs.getString(1)); }
    return out;
  }
}

